1	/**
2	 * @copyright
3	 * Copyright 2025 Intel Corporation.
4	 * SPDX-License-Identifier: Apache-2.0
5	 *
6	 * @test @b arm0102_fma_f32_sve
7	 * @parblock
8	 * SVE port of arm0102_fma_f32 (source: missing_testcases_20261009/
9	 * tests/cpu/arm-0102/arm0102_fma_f32.cpp; the fma.cpp branch of the
10	 * core-179 trigger recipe).
11	 *
12	 * Rotating fused multiply-add on f32 lanes with THREE source loads
13	 * (a, b, addend c — all asm-guaranteed ldr z; frandomf_scale(100.0f)
14	 * lane fill so no NaN/Inf):
15	 *   fma  — vfmaq(c, a, b)          = c + a*b   -> svmla_f32_x(c, a, b)
16	 *   fms  — vfmsq(c, a, b)          = c - a*b   -> svmsb_f32_x(c, a, b)
17	 *   fnma — vneg(vfms(vneg(c),a,b)) = c + a*b   (nested, kept verbatim)
18	 *   fnms — vneg(vfma(vneg(c),a,b)) = c - a*b   (nested, kept verbatim)
19	 * The fnma/fnms cases are numerically equal to fma/fms but traverse a
20	 * different instruction sequence (neg + fma + neg) — that is the
21	 * original's datapath-probing design, preserved.
22	 *
23	 * pg4 sub-block predicates preserve the 4-lane NEON semantics;
24	 * svcntw() elements (runtime VL) of buffer slack cover the asm full-VL
25	 * ldr z at the final sub-block (documented deviation from the mask_sve
26	 * template). Back-to-back str z -> ldr z -> str z amplifier.
27	 * @endparblock
28	 */
29	
30	#include "sandstone.h"
31	#include <cstdint>
32	#include <cstring>
33	#include <cstdlib>
34	
35	#if defined(__aarch64__)
36	#include <arm_sve.h>
37	#include <sys/auxv.h>
38	
39	#ifndef HWCAP_SVE
40	#define HWCAP_SVE (1 << 22)
41	#endif
42	#endif
43	
44	#define ARM0102_FMA_F32_SVE_COUNT 1024
45	/* 尾部 asm 全宽读松弛 = 运行时 svcntw(): 最末子块 ldr z 读到
46	 * (COUNT-1)+svcntw() 个元素, slack=svcntw() 严格充分 (任意 VL,
47	 * movbe_slf_sweep VL-portable 范式) */
48	
49	struct Arm0102FmaF32SveData {
50	    float *srcA;
51	    float *srcB;
52	    float *srcC;
53	    float *expected;
54	};
55	
56	#if defined(__aarch64__)
57	
58	#define FMA_SVE_SUBLANES 4
59	
60	static inline void store_vec_sve(void *addr, svfloat32_t val) {
61	    svbool_t pg = svwhilelt_b32((uint64_t)0, (uint64_t)FMA_SVE_SUBLANES);
62	    svst1_f32(pg, static_cast<float *>(addr), val);
63	}
64	
65	static inline svfloat32_t load_vec_sve(const void *addr) {
66	    svfloat32_t res;
67	    __asm__ volatile ("ldr %0, [%1]" : "=w"(res) : "r"(addr) : "memory");
68	    return res;
69	}
70	
71	/* 旋转 FMA 载荷 (相位 i%4); vfmaq(d,a,b)=d+a*b, vfmsq=d-a*b, vnegq 取反 */
72	static inline svfloat32_t fma_rotating_sve(svbool_t pg, svfloat32_t a, svfloat32_t b,
73	                                           svfloat32_t c, int phase)
74	{
75	    switch (phase % 4) {
76	        case 0: return svmla_f32_x(pg, c, a, b);                                   /* fma  */
77	        case 1: return svmsb_f32_x(pg, c, a, b);                                   /* fms  */
78	        case 2: return svneg_f32_x(pg, svmsb_f32_x(pg, svneg_f32_x(pg, c), a, b)); /* fnma */
79	        default: return svneg_f32_x(pg, svmla_f32_x(pg, svneg_f32_x(pg, c), a, b));/* fnms */
80	    }
81	}
82	
83	#endif
84	
85	static int arm0102_fma_f32_sve_init(struct test *test) {
86	#if defined(__aarch64__)
87	    unsigned long hwcap = getauxval(AT_HWCAP);
88	    if ((hwcap & HWCAP_SVE) == 0) {
89	        log_skip(CpuNotSupportedSkipCategory,
90	                 "to be implemented (placeholder): ARM SVE required for arm0102_fma_f32_sve");
91	        return EXIT_SKIP;
92	    }
93	
94	    const int slack = svcntw();   /* asm ldr z 尾批松弛, 见文件头注释 */
95	    const size_t total = (size_t)(ARM0102_FMA_F32_SVE_COUNT + slack) * sizeof(float);
96	    auto *data = static_cast<Arm0102FmaF32SveData *>(malloc(sizeof(Arm0102FmaF32SveData)));
97	    data->srcA = static_cast<float *>(aligned_alloc(64, total));
98	    data->srcB = static_cast<float *>(aligned_alloc(64, total));
99	    data->srcC = static_cast<float *>(aligned_alloc(64, total));
100	    data->expected = static_cast<float *>(aligned_alloc(64, total));
101	
102	    /* 逐 lane 缩放随机 (raw bits 会出 NaN/Inf — 原版语义) */
103	    for (int i = 0; i < ARM0102_FMA_F32_SVE_COUNT; i++) {
104	        data->srcA[i] = frandomf_scale(100.0f);
105	        data->srcB[i] = frandomf_scale(100.0f);
106	        data->srcC[i] = frandomf_scale(100.0f);
107	    }
108	
109	    /* golden: 与 run 相同的子块结构 + 相位 = 子块序号
110	     * (base+sub)/FMA_SVE_SUBLANES, 同 SVE 单元; 原式 (base+sub)%4 恒为 0
111	     * (base 是 svcntw() 倍数、sub 是 4 的倍数), 旋转失效 */
112	    const int lanes = svcntw();
113	    svbool_t pg4 = svwhilelt_b32((uint64_t)0, (uint64_t)FMA_SVE_SUBLANES);
114	    for (int base = 0; base < ARM0102_FMA_F32_SVE_COUNT; base += lanes) {
115	        const int n = (ARM0102_FMA_F32_SVE_COUNT - base < lanes)
116	                          ? ARM0102_FMA_F32_SVE_COUNT - base : lanes;
117	        for (int sub = 0; sub < n; sub += FMA_SVE_SUBLANES) {
118	            const int phase = (base + sub) / FMA_SVE_SUBLANES;
119	            float av[8], bv[8], cv[8], ov[8];
120	            for (int k = 0; k < FMA_SVE_SUBLANES && sub + k < n; ++k) {
121	                av[k] = data->srcA[base + sub + k];
122	                bv[k] = data->srcB[base + sub + k];
123	                cv[k] = data->srcC[base + sub + k];
124	            }
125	            svfloat32_t va = svld1_f32(pg4, av), vb = svld1_f32(pg4, bv), vc = svld1_f32(pg4, cv);
126	            svfloat32_t res = fma_rotating_sve(pg4, va, vb, vc, phase);
127	            svst1_f32(pg4, ov, res);
128	            for (int k = 0; k < FMA_SVE_SUBLANES && sub + k < n; ++k)
129	                data->expected[base + sub + k] = ov[k];
130	        }
131	    }
132	
133	    test->data = data;
134	    return EXIT_SUCCESS;
135	#else
136	    (void)test;
137	    log_skip(CpuNotSupportedSkipCategory,
138	             "to be implemented (placeholder): ARM SVE required for arm0102_fma_f32_sve");
139	    return EXIT_SKIP;
140	#endif
141	}
142	
143	#if defined(__aarch64__)
144	static int arm0102_fma_f32_sve_run(struct test *test, int cpu) {
145	    (void)cpu;
146	    auto *data = static_cast<Arm0102FmaF32SveData *>(test->data);
147	
148	    float *temp = static_cast<float *>(aligned_alloc(64, (size_t)(ARM0102_FMA_F32_SVE_COUNT + svcntw()) * sizeof(float)));
149	    float *dst  = static_cast<float *>(aligned_alloc(64, (size_t)(ARM0102_FMA_F32_SVE_COUNT + svcntw()) * sizeof(float)));
150	
151	    TEST_LOOP(test, 1 << 13) {
152	        for (int base = 0; base < ARM0102_FMA_F32_SVE_COUNT; base += svcntw()) {
153	            const int n = (ARM0102_FMA_F32_SVE_COUNT - base < svcntw())
154	                              ? ARM0102_FMA_F32_SVE_COUNT - base : svcntw();
155	            for (int sub = 0; sub < n; sub += FMA_SVE_SUBLANES) {
156	                /* 3 源加载 (a, b, 加数 c): asm 保证的 ldr z */
157	                svfloat32_t a = load_vec_sve(data->srcA + base + sub);
158	                svfloat32_t b = load_vec_sve(data->srcB + base + sub);
159	                svfloat32_t c = load_vec_sve(data->srcC + base + sub);
160	                svbool_t pg4 = svwhilelt_b32((uint64_t)0, (uint64_t)FMA_SVE_SUBLANES);
161	
162	                svfloat32_t res = fma_rotating_sve(pg4, a, b, c, (base + sub) / FMA_SVE_SUBLANES);
163	
164	                store_vec_sve(temp + base + sub, res);
165	                store_vec_sve(dst + base + sub, load_vec_sve(temp + base + sub));
166	            }
167	        }
168	
169	        if (memcmp(dst, data->expected, (size_t)ARM0102_FMA_F32_SVE_COUNT * sizeof(float)) != 0) {
170	            report_fail_msg("arm0102_fma_f32_sve data miscompare");
171	        }
172	    }
173	
174	    free(dst);
175	    free(temp);
176	    return EXIT_SUCCESS;
177	}
178	#else
179	static int arm0102_fma_f32_sve_run(struct test *test, int cpu) {
180	    (void)test; (void)cpu;
181	    log_skip(CpuNotSupportedSkipCategory,
182	             "to be implemented (placeholder): ARM SVE required for arm0102_fma_f32_sve");
183	    return EXIT_SKIP;
184	}
185	#endif
186	
187	static int arm0102_fma_f32_sve_cleanup(struct test *test) {
188	    auto *data = static_cast<Arm0102FmaF32SveData *>(test->data);
189	    if (data) {
190	        free(data->srcA);
191	        free(data->srcB);
192	        free(data->srcC);
193	        free(data->expected);
194	        free(data);
195	    }
196	    return EXIT_SUCCESS;
197	}
198	
