 * (COUNT-1)+svcntw() 个元素, slack=svcntw() 严格充分 (任意 VL,
 * movbe_slf_sweep VL-portable 范式) */

struct Arm0102KregNotSveData {
    uint32_t *srcA;
    uint32_t *srcB;
    uint32_t *expected;
};

#if defined(__aarch64__)

#define KNOT_SVE_SUBLANES 4

static inline void store_vec_sve(void *addr, svuint32_t val) {
    svbool_t pg = svwhilelt_b32((uint64_t)0, (uint64_t)KNOT_SVE_SUBLANES);
    svst1_u32(pg, static_cast<uint32_t *>(addr), val);
}

static inline svuint32_t load_vec_sve(const void *addr) {
    svuint32_t res;
    __asm__ volatile ("ldr %0, [%1]" : "=w"(res) : "r"(addr) : "memory");
    return res;
}

/* 旋转取反逻辑载荷 (相位 i%4): nand/nor/xnor/nandnot */
static inline svuint32_t not_rotating_sve(svbool_t pg, svuint32_t a, svuint32_t b, int phase)
{
    switch (phase % 4) {
        case 0: return svnot_u32_x(pg, svand_u32_x(pg, a, b));
        case 1: return svnot_u32_x(pg, svorr_u32_x(pg, a, b));
        case 2: return svnot_u32_x(pg, sveor_u32_x(pg, a, b));
        default: return svnot_u32_x(pg, svbic_u32_x(pg, a, b));
    }
}

#endif

static int arm0102_kreg_not_sve_init(struct test *test) {
#if defined(__aarch64__)
    unsigned long hwcap = getauxval(AT_HWCAP);
    if ((hwcap & HWCAP_SVE) == 0) {
        log_skip(CpuNotSupportedSkipCategory,
                 "to be implemented (placeholder): ARM SVE required for arm0102_kreg_not_sve");
        return EXIT_SKIP;
    }

    const int slack = svcntw();   /* asm ldr z 尾批松弛, 见文件头注释 */
    const size_t total = (size_t)(ARM0102_KREG_NOT_SVE_COUNT + slack) * sizeof(uint32_t);
    auto *data = static_cast<Arm0102KregNotSveData *>(malloc(sizeof(Arm0102KregNotSveData)));
    data->srcA = static_cast<uint32_t *>(aligned_alloc(64, total));
    data->srcB = static_cast<uint32_t *>(aligned_alloc(64, total));
    data->expected = static_cast<uint32_t *>(aligned_alloc(64, total));

    memset_random(data->srcA, total);
    memset_random(data->srcB, total);

    const int lanes = svcntw();
    svbool_t pg4 = svwhilelt_b32((uint64_t)0, (uint64_t)KNOT_SVE_SUBLANES);
    for (int base = 0; base < ARM0102_KREG_NOT_SVE_COUNT; base += lanes) {
        const int n = (ARM0102_KREG_NOT_SVE_COUNT - base < lanes)
                          ? ARM0102_KREG_NOT_SVE_COUNT - base : lanes;
        for (int sub = 0; sub < n; sub += KNOT_SVE_SUBLANES) {
            /* 相位 = 子块序号 (base+sub)/KNOT_SVE_SUBLANES, 按子块旋转;
             * 原式 (base+sub)%4 恒为 0 (base 是 svcntw() 倍数、sub 是 4 的倍数) */
