1	/**
2	 * @copyright
3	 * Copyright 2025 Intel Corporation.
4	 * SPDX-License-Identifier: Apache-2.0
5	 *
6	 * @test @b swizzle_sve
7	 * @parblock
8	 * SVE port of swizzle: the pairwise-swap permutation (0↔1, 2↔3, ...) via
9	 * svtbl byte-level table lookup on an SVE vector — the SVE1 general
10	 * permute primitive (NEON vrev64q has no direct SVE1 counterpart).
11	 * Reference is the same scalar gather with the same perm table.
12	 * @endparblock
13	 */
14	
15	#include <sandstone.h>
16	#include <cstdint>
17	#include <cstdio>
18	#include <random>
19	#include <cstring>
20	#include <atomic>
21	
22	#ifdef __aarch64__
23	#include <arm_sve.h>
24	#include <sys/auxv.h>
25	
26	#ifndef HWCAP_SVE
27	#define HWCAP_SVE (1 << 22)
28	#endif
29	#endif
30	
31	// 标量参考实现（与原版一致）
32	static void swizzle_reference(const float *src, float *dst, const int *perm) {
33	    for (int i = 0; i < 8; ++i) {
34	        dst[i] = src[perm[i]];
35	    }
36	}
37	
38	static int swizzle_sve_init(struct test *test) {
39	    (void)test;
40	#ifdef __aarch64__
41	    unsigned long hwcap = getauxval(AT_HWCAP);
42	    if ((hwcap & HWCAP_SVE) == 0) {
43	        log_skip(CpuNotSupportedSkipCategory,
44	                 "to be implemented (placeholder): ARM SVE required for swizzle_sve");
45	        return EXIT_SKIP;
46	    }
47	#endif
48	    return EXIT_SUCCESS;
49	}
50	
51	#ifdef __aarch64__
52	static int swizzle_sve_run(struct test *test, int cpu) {
53	    (void)cpu;
54	
55	    std::mt19937 rng(std::random_device{}());
56	    // 置换模式：交换每对相邻元素 (0↔1, 2↔3, 4↔5, 6↔7) —— 与原版一致
57	    int perm[8] = {1, 0, 3, 2, 5, 4, 7, 6};
58	
59	    float src[8];
60	    float dst_ref[8];
61	    float dst_hw[8];
62	
63	    static std::atomic<uint64_t> iter{0};
64	
65	    do {
66	        for (int i = 0; i < 8; ++i) src[i] = (float)((int)(rng() % 20000) - 10000) / 100.0f;
67	        swizzle_reference(src, dst_ref, perm);
68	
69	        /* === SVE 实现: svtbl 字节表查找做 32-bit lane 置换 ===
70	         * 每 float 4 字节: lane i 的字节来自 lane perm[i]。
71	         * 索引表按字节粒度: byte j of lane i ← byte j of lane perm[i]. */
72	        const int lanes = svcntw();          /* 谓词宽度, ≥ 8 时一批完成 */
73	        uint8_t srcbytes[32];
74	        uint8_t outbytes[32];
75	        uint8_t idx[32];
76	        int covered = (lanes >= 8) ? 8 : lanes;
77	        memcpy(srcbytes, src, 8 * sizeof(float));
78	        for (int i = 0; i < covered; ++i)
79	            for (int b = 0; b < 4; ++b)
80	                idx[i * 4 + b] = (uint8_t)(perm[i] * 4 + b);
81	
82	        svbool_t pg = svwhilelt_b8((uint64_t)0, (uint64_t)(covered * 4));
83	        svuint8_t vidx = svld1_u8(pg, idx);
84	        svuint8_t vsrc = svld1_u8(pg, srcbytes);
85	        svuint8_t vout = svtbl_u8(vsrc, vidx);
86	        svst1_u8(pg, outbytes, vout);
87	        memcpy(dst_hw, outbytes, covered * sizeof(float));
88	
89	        /* covered < 8 时(小 VL)剩余 lane 用标量补齐 —— 保持 8 元素完整比对 */
90	        for (int i = covered; i < 8; ++i)
91	            dst_hw[i] = src[perm[i]];
92	
93	        bool passed = (memcmp(dst_hw, dst_ref, sizeof(dst_hw)) == 0);
94	        uint64_t iteration = iter.fetch_add(1, std::memory_order_relaxed);
95	
96	        const char *color = passed ? "\033[32m" : "\033[31m";
97	        const char *result_str = passed ? "PASS" : "FAIL";
98	        fprintf(stderr, "swizzle_sve: Iteration %lu, input[0..3] = %.2f, %.2f, %.2f, %.2f, result = %s%s\033[0m\n",
99	                iteration, src[0], src[1], src[2], src[3], color, result_str);
100	
101	        if (!passed) {
102	            report_fail_msg("swizzle_sve: data mismatch");
103	            return EXIT_FAILURE;
104	        }
