            svbool_t pg = svwhilelt_b8((uint64_t)0, (uint64_t)(n * 4));

            /* 直接堆访存 (无栈中转): 修复版 —— 原版被测路径是
             * 堆 store(swapped) 后紧跟堆 reload, 栈中转会改变被测微操作序列 */
