            svuint8_t reloaded = svld1_u8(pg, (const uint8_t *)(data->swapped + base));

            /* 再交换一次还原 (同一索引表, svtbl 可逆) */
            svuint8_t vrestored = svtbl_u8(reloaded, vidx);
            uint8_t out_bytes[64];
