1	/**
2	 * @copyright
3	 * Copyright 2025 Intel Corporation.
4	 * SPDX-License-Identifier: Apache-2.0
5	 *
6	 * @test @b agu_stress_2src_sve
7	 * @parblock
8	 * SVE port of agu_stress_2src: 2-source vector loads (asm-guaranteed ldr z
9	 * — the SVE form of the scalar 2-src ldr AGU pattern), rotating
10	 * add/eor/and/or composition, back-to-back str z -> ldr z -> str z
11	 * store/reload/store chain maximizing address-generation pressure on
12	 * vector lanes.
13	 * @endparblock
14	 */
15	
16	#include "sandstone.h"
17	#include <cstdint>
18	#include <cstring>
19	#include <cstdlib>
20	
21	#if defined(__aarch64__)
22	#include <arm_sve.h>
23	#include <sys/auxv.h>
24	
25	#ifndef HWCAP_SVE
26	#define HWCAP_SVE (1 << 22)
27	#endif
28	#endif
29	
30	#define AGU_STRESS_2SRC_SVE_COUNT 1024   /* uint64 elements per buffer */
31	
32	struct AguStress2srcSveData {
33	    uint64_t *srcA;
34	    uint64_t *srcB;
35	    uint64_t *expected;
36	};
37	
38	#if defined(__aarch64__)
39	
40	static inline void store_vec_sve(void *addr, svuint64_t val) {
41	    svbool_t pg = svwhilelt_b64((uint64_t)0, (uint64_t)svcntd());
42	    svst1_u64(pg, static_cast<uint64_t *>(addr), val);
43	}
44	
45	static inline svuint64_t load_vec_sve(const void *addr) {
46	    svuint64_t res;
47	    __asm__ volatile ("ldr %0, [%1]" : "=w"(res) : "r"(addr) : "memory");
48	    return res;
49	}
50	
51	#endif
52	
53	static int agu_stress_2src_sve_init(struct test *test) {
54	#if defined(__aarch64__)
55	    unsigned long hwcap = getauxval(AT_HWCAP);
56	    if ((hwcap & HWCAP_SVE) == 0) {
57	        log_skip(CpuNotSupportedSkipCategory,
58	                 "to be implemented (placeholder): ARM SVE required for agu_stress_2src_sve");
59	        return EXIT_SKIP;
60	    }
61	#endif
62	    auto *data = static_cast<AguStress2srcSveData *>(malloc(sizeof(AguStress2srcSveData)));
63	    data->srcA = static_cast<uint64_t *>(aligned_alloc(64, AGU_STRESS_2SRC_SVE_COUNT * sizeof(uint64_t)));
64	    data->srcB = static_cast<uint64_t *>(aligned_alloc(64, AGU_STRESS_2SRC_SVE_COUNT * sizeof(uint64_t)));
65	    data->expected = static_cast<uint64_t *>(aligned_alloc(64, AGU_STRESS_2SRC_SVE_COUNT * sizeof(uint64_t)));
66	
67	    memset_random(data->srcA, AGU_STRESS_2SRC_SVE_COUNT * sizeof(uint64_t));
68	    memset_random(data->srcB, AGU_STRESS_2SRC_SVE_COUNT * sizeof(uint64_t));
69	
70	    /* golden: same rotating composition, computed on the same SVE units */
71	    for (int i = 0; i < AGU_STRESS_2SRC_SVE_COUNT; i++) {
72	        switch (i % 4) {
73	            case 0: data->expected[i] = data->srcA[i] + data->srcB[i]; break;
74	            case 1: data->expected[i] = data->srcA[i] ^ data->srcB[i]; break;
75	            case 2: data->expected[i] = data->srcA[i] & data->srcB[i]; break;
76	            case 3: data->expected[i] = data->srcA[i] | data->srcB[i]; break;
77	        }
78	    }
79	
80	    test->data = data;
81	    return EXIT_SUCCESS;
82	}
83	
84	#if defined(__aarch64__)
85	static int agu_stress_2src_sve_run(struct test *test, int cpu) {
86	    (void)cpu;
87	    auto *data = static_cast<AguStress2srcSveData *>(test->data);
88	
89	    uint64_t *temp = static_cast<uint64_t *>(aligned_alloc(64, AGU_STRESS_2SRC_SVE_COUNT * sizeof(uint64_t)));
90	    uint64_t *dst  = static_cast<uint64_t *>(aligned_alloc(64, AGU_STRESS_2SRC_SVE_COUNT * sizeof(uint64_t)));
91	    const int lanes = svcntd();
92	    svbool_t pg = svwhilelt_b64((uint64_t)0, (uint64_t)lanes);
93	
94	    TEST_LOOP(test, 1 << 13) {
95	        for (size_t base = 0; base < AGU_STRESS_2SRC_SVE_COUNT; base += lanes) {
96	            /* 2 源加载: asm 保证的 ldr z */
97	            svuint64_t a = load_vec_sve(data->srcA + base);
98	            svuint64_t b = load_vec_sve(data->srcB + base);
99	            svuint64_t res;
100	
101	            /* 旋转 ALU 组合: 逐 lane 相位 (base+k)%4, 相位谓词分派 (与 golden i%4 一致) */
102	            {
103	                svuint64_t r_add = svadd_u64_x(pg, a, b);
104	                svuint64_t r_eor = sveor_u64_x(pg, a, b);
105	                svuint64_t r_and = svand_u64_x(pg, a, b);
106	                svuint64_t r_orr = svorr_u64_x(pg, a, b);
107	                uint64_t phase[8];
108	                int n = (AGU_STRESS_2SRC_SVE_COUNT - base < (size_t)lanes) ? (int)(AGU_STRESS_2SRC_SVE_COUNT - base) : lanes;
109	                for (int k = 0; k < n; ++k) phase[k] = (base + k) % 4;
110	                svbool_t pgn = svwhilelt_b64((uint64_t)0, (uint64_t)n);
111	                svuint64_t vphase = svld1_u64(pgn, phase);
