70	    uint8_t vidx_bytes[64];
71	    for (int i = 0; i < lanes && i < 16; ++i)
72	        for (int b = 0; b < 4; ++b)
73	            vidx_bytes[i * 4 + b] = (uint8_t)(i * 4 + idx4[b]);
74	    svbool_t pg_batch = svwhilelt_b8((uint64_t)0, (uint64_t)(lanes < 16 ? lanes * 4 : 64));
75	    svuint8_t vidx = svld1_u8(pg_batch, vidx_bytes);
76	
77	    TEST_LOOP(test, 1 << 13) {
78	        for (size_t base = 0; base < MOVBE_BUFFER_SIZE; base += lanes) {
79	            int n = (MOVBE_BUFFER_SIZE - base < (size_t)lanes) ? (int)(MOVBE_BUFFER_SIZE - base) : lanes;
80	            svbool_t pg = svwhilelt_b8((uint64_t)0, (uint64_t)(n * 4));
81	
